/**
 * Voice manifest — maps keys to audio file paths + fallback text.
 * Audio generated by ElevenLabs (primary) or macOS `say` (fallback).
 * Fallback text used by Web Speech API when no audio clip is loaded.
 */

const BASE = "/audio/voices/";

export interface VoiceEntry {
  file: string;
  text: string;
}

function entry(filename: string, text: string): VoiceEntry {
  return { file: BASE + filename, text };
}

