/** Helper to get just the file path for a key */
export function getVoicePath(key: string): string | undefined {
  return voiceManifest[key]?.file;
}

/** Helper to get fallback text for a key */
export function getVoiceText(key: string): string {
  return voiceManifest[key]?.text || key;
}

/** All voice keys for preloading */
export const allVoiceKeys = Object.keys(voiceManifest);

